// ---- _shared/mp3.ts
// MP3 check done on the server, on the bytes actually received.
// Not a full decoder: it walks the MPEG audio frame chain and refuses anything that is not a
// consistent MPEG-1/2/2.5 Layer III stream. Duration comes from the frames, not from the browser.

export type Mp3Result =
  | { ok: true; durationMs: number; frames: number; sampleRate: number; audioBytes: number }
  | { ok: false; reason: string };

const BITRATES_V1 = [0, 32, 40, 48, 56, 64, 80, 96, 112, 128, 160, 192, 224, 256, 320];
const BITRATES_V2 = [0, 8, 16, 24, 32, 40, 48, 56, 64, 80, 96, 112, 128, 144, 160];
const RATES: Record<number, number[]> = { 3: [44100, 48000, 32000], 2: [22050, 24000, 16000], 0: [11025, 12000, 8000] };

export const MP3_LIMITS = {
  maxId3Bytes: 512 * 1024,     // cover art etc.; more is not plausible for a ringtone
  minFrames: 4,
  minAudioShare: 0.9,          // frames must cover ≥90% of the bytes after the leading tag
  maxTrailingJunk: 2048,
};

type Header = { version: number; sampleRate: number; length: number; samples: number };

function parseHeader(b: Uint8Array, i: number): Header | null {
  if (i + 4 > b.length) return null;
  if (b[i] !== 0xff || (b[i + 1] & 0xe0) !== 0xe0) return null;          // 11-bit sync
  const version = (b[i + 1] >> 3) & 3;                                    // 0=2.5, 2=2, 3=1, 1=reserved
  const layer = (b[i + 1] >> 1) & 3;                                      // 1 = Layer III
  const brIdx = (b[i + 2] >> 4) & 15;
  const srIdx = (b[i + 2] >> 2) & 3;
  const pad = (b[i + 2] >> 1) & 1;
  if (version === 1 || layer !== 1 || brIdx === 0 || brIdx === 15 || srIdx === 3) return null;
  const kbps = (version === 3 ? BITRATES_V1 : BITRATES_V2)[brIdx];
  const sampleRate = RATES[version][srIdx];
  const samples = version === 3 ? 1152 : 576;
  const length = Math.floor(((samples / 8) * kbps * 1000) / sampleRate) + pad;
  if (length < 24) return null;
  return { version, sampleRate, length, samples };
}

function id3v2Size(b: Uint8Array): number {
  if (b.length < 10 || b[0] !== 0x49 || b[1] !== 0x44 || b[2] !== 0x33) return 0;   // "ID3"
  if ((b[6] | b[7] | b[8] | b[9]) & 0x80) return -1;                                  // not syncsafe
  const size = (b[6] << 21) | (b[7] << 14) | (b[8] << 7) | b[9];
  const footer = b[5] & 0x10 ? 10 : 0;
  return 10 + size + footer;
}

function isTrailingTag(b: Uint8Array, i: number): boolean {
  const rest = b.length - i;
  if (rest === 128 && b[i] === 0x54 && b[i + 1] === 0x41 && b[i + 2] === 0x47) return true;            // ID3v1 "TAG"
  const ape = [0x41, 0x50, 0x45, 0x54, 0x41, 0x47, 0x45, 0x58];                                          // "APETAGEX"
  if (rest >= 32 && rest <= 65536 && ape.every((c, k) => b[i + k] === c)) return true;   // bounded: no smuggled payloads
  return false;
}

export function checkMp3(bytes: Uint8Array): Mp3Result {
  if (bytes.length < 128) return { ok: false, reason: 'too_small' };
  const tag = id3v2Size(bytes);
  if (tag < 0) return { ok: false, reason: 'bad_id3' };
  if (tag > MP3_LIMITS.maxId3Bytes) return { ok: false, reason: 'id3_too_large' };
  if (tag >= bytes.length) return { ok: false, reason: 'no_audio' };

  let i = tag;
  // some encoders pad between the tag and the first frame
  let skipped = 0;
  while (i < bytes.length && bytes[i] === 0 && skipped < 4096) { i++; skipped++; }

  let frames = 0, samples = 0, audioBytes = 0, version = -1, sampleRate = 0;
  while (i < bytes.length) {
    const h = parseHeader(bytes, i);
    if (!h) break;
    if (version === -1) { version = h.version; sampleRate = h.sampleRate; }
    else if (h.version !== version || h.sampleRate !== sampleRate) return { ok: false, reason: 'inconsistent_stream' };
    if (i + h.length > bytes.length) {                       // last frame cut short: accept, but don't count it
      audioBytes += bytes.length - i; i = bytes.length; break;
    }
    frames++; samples += h.samples; audioBytes += h.length; i += h.length;
  }
  if (frames < MP3_LIMITS.minFrames) return { ok: false, reason: 'not_mp3' };
  if (i < bytes.length && !isTrailingTag(bytes, i) && bytes.length - i > MP3_LIMITS.maxTrailingJunk) {
    return { ok: false, reason: 'corrupt' };
  }
  if (audioBytes < (bytes.length - tag) * MP3_LIMITS.minAudioShare && !isTrailingTag(bytes, i)) {
    return { ok: false, reason: 'not_mostly_audio' };
  }
  return { ok: true, durationMs: Math.round((samples * 1000) / sampleRate), frames, sampleRate, audioBytes };
}

export async function sha256Hex(bytes: Uint8Array): Promise<string> {
  const d = new Uint8Array(await crypto.subtle.digest('SHA-256', bytes));
  let s = '';
  for (const x of d) s += x.toString(16).padStart(2, '0');
  return s;
}


// ---- _shared/http.ts
// Small HTTP helpers shared by the library functions. Runtime-neutral (Web APIs only).

export function corsHeaders(req: Request, allowedOrigins: string[]): Record<string, string> {
  const origin = req.headers.get('origin') ?? '';
  const h: Record<string, string> = { 'Vary': 'Origin' };
  if (origin && allowedOrigins.includes(origin)) {
    h['Access-Control-Allow-Origin'] = origin;
    h['Access-Control-Allow-Methods'] = 'POST, OPTIONS';
    h['Access-Control-Allow-Headers'] = 'authorization, apikey, content-type, x-client-info, x-library-meta';
    h['Access-Control-Max-Age'] = '600';
  }
  return h;
}

export function json(body: unknown, status: number, extra: Record<string, string> = {}): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store', ...extra },
  });
}

export function bearer(req: Request): string | null {
  const h = req.headers.get('authorization') ?? '';
  const m = /^Bearer\s+(\S+)$/i.exec(h);
  return m ? m[1] : null;
}

// constant-time comparison for shared secrets
export function safeEqual(a: string, b: string): boolean {
  const x = new TextEncoder().encode(a), y = new TextEncoder().encode(b);
  let diff = x.length ^ y.length;
  for (let i = 0; i < Math.max(x.length, y.length); i++) diff |= (x[i] ?? 0) ^ (y[i] ?? 0);
  return diff === 0;
}

// bytes readCapped already pulled from a body it then gave up on: discardBody's budget is per request
const consumed = new WeakMap<Request, number>();

// read at most `max` bytes; returns null if the body is larger (stops reading early and leaves the
// rest unread but unlocked, so the handler's discardBody can still drain it)
export async function readCapped(req: Request, max: number): Promise<Uint8Array | null | 'missing'> {
  const declared = req.headers.get('content-length');
  if (declared !== null && (!/^\d+$/.test(declared) || Number(declared) > max)) return null;
  if (!req.body) return 'missing';
  const reader = req.body.getReader();
  const parts: Uint8Array[] = [];
  let total = 0;
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    total += value.byteLength;
    if (total > max) { reader.releaseLock(); consumed.set(req, total); return null; }
    parts.push(value);
  }
  const out = new Uint8Array(total);
  let o = 0;
  for (const p of parts) { out.set(p, o); o += p.byteLength; }
  return out;
}

// read and drop a request body nobody read (at most `max` bytes per request in total, counting what
// readCapped already read, then cancel).
// On the hosted runtime a response sent while the client is still sending the body never arrives:
// staging T9b (11 MiB, 413 decided from content-length) hung until the 150 s wall clock → 503.
// A body DECLARED larger than `max` (or with a malformed length) is cancelled without reading any
// of it: draining part of it would not help that client and only costs this function time.
export async function discardBody(req: Request, max: number): Promise<void> {
  if (!req.body || req.body.locked) return;            // locked = a reader is still busy with it (fully read)
  const declared = req.headers.get('content-length');
  if (declared !== null && (!/^\d+$/.test(declared) || Number(declared) > max)) {
    await req.body.cancel().catch(() => {});
    return;
  }
  const reader = req.body.getReader();
  let total = consumed.get(req) ?? 0;
  try {
    for (;;) {
      const { done, value } = await reader.read();
      if (done) return;
      total += value.byteLength;
      if (total > max) { await reader.cancel(); return; }
    }
  } catch { /* client went away */ }
}

export function decodeMeta(header: string | null): Record<string, unknown> | null {
  if (!header || header.length > 4096) return null;
  try {
    const b64 = header.replace(/-/g, '+').replace(/_/g, '/');
    const bin = atob(b64 + '==='.slice((b64.length + 3) % 4));
    const bytes = Uint8Array.from(bin, (c) => c.charCodeAt(0));
    const v = JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(bytes));
    return v && typeof v === 'object' && !Array.isArray(v) ? v : null;
  } catch {
    return null;
  }
}

export const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;


// ---- _shared/r2.ts
// Minimal S3-compatible client for Cloudflare R2 (media backup). AWS Signature V4, path-style URLs,
// region "auto". Only what the janitor needs: PUT, DELETE, LIST (ListObjectsV2). No SDK, no dependencies.
// Runtime-neutral (Web Crypto + fetch), so the same code runs in Deno and in the local Node tests.

export type R2Config = { endpoint: string; bucket: string; accessKeyId: string; secretAccessKey: string; region?: string };

const r2enc = new TextEncoder();
const r2hex = (b: ArrayBuffer) => Array.from(new Uint8Array(b)).map((x) => x.toString(16).padStart(2, '0')).join('');
async function r2Sha256(data: Uint8Array | string): Promise<string> {
  return r2hex(await crypto.subtle.digest('SHA-256', typeof data === 'string' ? r2enc.encode(data) : data));
}
async function r2Hmac(key: ArrayBuffer | Uint8Array, msg: string): Promise<ArrayBuffer> {
  const k = await crypto.subtle.importKey('raw', key, { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  return crypto.subtle.sign('HMAC', k, r2enc.encode(msg));
}
// RFC 3986 encoding as S3 expects ('/' kept in paths)
const r2EncSeg = (s: string) => encodeURIComponent(s).replace(/[!'()*]/g, (c) => '%' + c.charCodeAt(0).toString(16).toUpperCase());
const r2EncPath = (p: string) => p.split('/').map(r2EncSeg).join('/');

export type Signed = { url: string; headers: Record<string, string> };

/** Signs one request. `amzDate` is injectable for tests (yyyymmddThhmmssZ). */
export async function signV4(method: string, host: string, path: string, query: Record<string, string>, headers: Record<string, string>,
  payloadHash: string, cfg: { accessKeyId: string; secretAccessKey: string; region: string; service?: string }, amzDate: string): Promise<Signed> {
  const service = cfg.service ?? 's3', date = amzDate.slice(0, 8);
  const h: Record<string, string> = { ...headers, host, 'x-amz-date': amzDate, 'x-amz-content-sha256': payloadHash };
  const names = Object.keys(h).map((k) => k.toLowerCase()).sort();
  const lower: Record<string, string> = {}; for (const [k, v] of Object.entries(h)) lower[k.toLowerCase()] = String(v).trim().replace(/\s+/g, ' ');
  const canonQuery = Object.keys(query).sort().map((k) => `${r2EncSeg(k)}=${r2EncSeg(query[k])}`).join('&');
  const canonical = [method, r2EncPath(path), canonQuery, names.map((n) => `${n}:${lower[n]}\n`).join(''), names.join(';'), payloadHash].join('\n');
  const scope = `${date}/${cfg.region}/${service}/aws4_request`;
  const toSign = ['AWS4-HMAC-SHA256', amzDate, scope, await r2Sha256(canonical)].join('\n');
  let k = await r2Hmac(r2enc.encode('AWS4' + cfg.secretAccessKey), date);
  for (const part of [cfg.region, service, 'aws4_request']) k = await r2Hmac(k, part);
  const sig = r2hex(await r2Hmac(k, toSign));
  const out: Record<string, string> = { ...h };
  delete out.host;
  out.authorization = `AWS4-HMAC-SHA256 Credential=${cfg.accessKeyId}/${scope}, SignedHeaders=${names.join(';')}, Signature=${sig}`;
  return { url: `https://${host}${r2EncPath(path)}${canonQuery ? '?' + canonQuery : ''}`, headers: out };
}

const r2NowAmz = () => new Date().toISOString().replace(/[-:]/g, '').replace(/\.\d{3}/, '');

export function r2Client(cfg: R2Config, fetchFn: typeof fetch = fetch) {
  const host = new URL(cfg.endpoint).host;
  const sc = { accessKeyId: cfg.accessKeyId, secretAccessKey: cfg.secretAccessKey, region: cfg.region ?? 'auto' };
  const p = (key: string) => `/${cfg.bucket}/${key}`;
  return {
    async put(key: string, bytes: Uint8Array): Promise<'ok' | { error: string }> {
      const s = await signV4('PUT', host, p(key), {}, { 'content-type': 'audio/mpeg', 'content-length': String(bytes.byteLength) }, await r2Sha256(bytes), sc, r2NowAmz());
      const r = await fetchFn(s.url, { method: 'PUT', headers: s.headers, body: bytes });
      await r.arrayBuffer().catch(() => null);
      return r.ok ? 'ok' : { error: `r2 put ${r.status}` };
    },
    async del(key: string): Promise<'ok' | { error: string }> {
      const s = await signV4('DELETE', host, p(key), {}, {}, await r2Sha256(''), sc, r2NowAmz());
      const r = await fetchFn(s.url, { method: 'DELETE', headers: s.headers });
      await r.arrayBuffer().catch(() => null);
      return r.ok || r.status === 404 ? 'ok' : { error: `r2 delete ${r.status}` };     // already gone = fine
    },
    /** One page of keys (≤ 1000) with their last-modified time. */
    async list(token?: string): Promise<{ keys: { key: string; modified: number }[]; next?: string } | { error: string }> {
      const q: Record<string, string> = { 'list-type': '2', 'max-keys': '1000' };
      if (token) q['continuation-token'] = token;
      const s = await signV4('GET', host, `/${cfg.bucket}`, q, {}, await r2Sha256(''), sc, r2NowAmz());
      const r = await fetchFn(s.url, { method: 'GET', headers: s.headers });
      const xml = await r.text();
      if (!r.ok) return { error: `r2 list ${r.status}` };
      const keys = [...xml.matchAll(/<Contents>([\s\S]*?)<\/Contents>/g)].map((m) => ({
        key: (/<Key>([\s\S]*?)<\/Key>/.exec(m[1])?.[1] ?? '').replace(/&amp;/g, '&'),
        modified: Date.parse(/<LastModified>([\s\S]*?)<\/LastModified>/.exec(m[1])?.[1] ?? '') || 0,
      })).filter((k) => k.key);
      const next = /<IsTruncated>true<\/IsTruncated>/.test(xml) ? /<NextContinuationToken>([\s\S]*?)<\/NextContinuationToken>/.exec(xml)?.[1] : undefined;
      return { keys, next };
    },
  };
}


